def _validate_contract(model_name: str, value: Any) -> Any:
    errors = sorted(_VALIDATORS[model_name].iter_errors(value), key=lambda error: list(error.path))
    if errors:
        first = errors[0]
        location = '.'.join(str(part) for part in first.path) or '<root>'
        raise ValueError(f'{model_name} schema validation failed at {location}: {first.message}')
    return value

